// GET ?e_customer_id=<bill-to id>: the bill-to's most recent orders.
const q = $input.first().json.query || {};
const id = String(q.e_customer_id || '').trim();
if (!/^\d+$/.test(id)) return [{ json: { ok: false, statusCode: 400, body: { success: false, error: 'Missing or invalid e_customer_id.', step: 'validate' } } }];
return [{ json: { ok: true, customerId: id, pageSize: 100 } }];

// Eclipse Get Many returns one row per generation (ids like S2659464.0002)
// or per order; either way rows are grouped by base order id here.
const v = $('Validate').first().json;
const env = $input.first().json;
if (env.error) return [{ json: { statusCode: 502, body: { success: false, step: 'getSalesOrders',
  error: 'Eclipse GET /SalesOrders?BillTo=' + v.customerId + ' failed: ' + env.error + ' ' + JSON.stringify(env.message || '').substring(0, 500) } } }];
const rows = Array.isArray(env.results) ? env.results : [];
const pad = (g) => String(g).padStart(4, '0');
const money = (m) => (m && m.value != null ? Number(m.value) : null);
const byOrder = {};
const order = [];
for (const r of rows) {
  const base = String(r.id || '').split('.')[0];
  if (!base) continue;
  if (!byOrder[base]) { byOrder[base] = { order_id: base, last_modified: r.lastUpdateDateTime || '', generations: [] }; order.push(base); }
  const o = byOrder[base];
  for (const g of (Array.isArray(r.generations) ? r.generations : [])) {
    const gid = String(g.generationId);
    if (o.generations.some((x) => String(x.generation_id) === gid)) continue;
    o.generations.push({
      e_sorder_id: base + '.' + pad(gid), generation_id: Number(gid),
      invoice_number: g.invoiceNumber != null ? Number(g.invoiceNumber) : null,
      status: String(g.status || ''), order_date: g.orderDate || '',
      ship_to_id: String(g.shipToId || ''), ship_to_name: g.shipToName || '',
      po: g.poNumber || '', sales_total: money(g.salesTotal),
    });
  }
}
const orders = order.map((k) => byOrder[k]);
for (const o of orders) {
  o.generations.sort((a, b) => a.generation_id - b.generation_id);
  o.order_date = o.generations.reduce((d, g) => (g.order_date > d ? g.order_date : d), '');
}
orders.sort((a, b) => (b.order_date || '').localeCompare(a.order_date || ''));
return [{ json: { statusCode: 200, body: {
  success: true, e_customer_id: v.customerId, orders,
  // A full page means there may be older orders not listed.
  truncated: rows.length >= v.pageSize, page_size: v.pageSize,
} } }];
